import{funnel as g,perWeek as p,responseStats as w,weekly as y,stats as b,firstWeekKey as $}from"./derive.min.js";import{STATUS_LABELS as L}from"./labels.min.js";import{parseLocal as f}from"./dates.min.js";import{weekCardLines as d}from"./copy.min.js";import{WEEK_CARD_LAYOUT as D}from"./weekcard.min.js";const T=new Intl.DateTimeFormat("en-US",{month:"short",day:"numeric"}),C=new Intl.DateTimeFormat("en-US",{month:"long",day:"numeric",year:"numeric"});function x(e,s,t){return p(e,s,t).map((o,n,a)=>({label:T.format(f(o.key)),count:o.count,current:n===a.length-1}))}export function boardModel(e,s,t,o=8){const n=b(e,s,t);return{funnel:g(e,s).map(a=>({label:L[a.stage],count:a.count})),weeks:x(e,t,o),goal:e.settings.weeklyGoal,thisWeek:y(e,t),response:w(e,s),quiet:n.ghosted,open:n.open}}export const LAYOUT={title:{x:.05,y:.09},funnel:{x0:.05,y0:.22,x1:.46,y1:.9},weeks:{x0:.54,y0:.24,x1:.95,y1:.6},numbers:{x0:.54,y0:.7,x1:.95,y1:.92}};export function funnelBars(e,s=LAYOUT){const t=s.funnel,o=Math.max(1,...e.funnel.map(l=>l.count)),n=(t.y1-t.y0)/e.funnel.length,a=(t.x1-t.x0)*.42;return e.funnel.map((l,r)=>({x:t.x0+a,y:t.y0+n*r+n*.2,w:Math.max(.006,(t.x1-t.x0-a)*.85*l.count/o),h:n*.6,label:l.label,count:l.count}))}export function weekChart(e,s=LAYOUT){const t=s.weeks,o=Math.max(e.goal*1.25,...e.weeks.map(r=>r.count),1),n=(t.x1-t.x0)/e.weeks.length,a=r=>t.y1-(t.y1-t.y0)*r/o;return{bars:e.weeks.map((r,u)=>({x:t.x0+n*u+n*.18,w:n*.64,y:a(r.count),h:t.y1-a(r.count),label:r.label,count:r.count,current:r.current})),goalY:a(e.goal),x0:t.x0,x1:t.x1,baseline:t.y1}}export function cardChartBox(e,s,t=D.weeks){const o=(t.x1-t.x0)/s,n=(t.x0+t.x1)/2,a=o*e/2;return{...t,x0:n-a,x1:n+a}}export function weekCardModel(e,s,t){const o=s.weekCard,n=y(e,t),a=$(e),l=p(e,t,o.weeks).map(c=>c.key),r=a===null?l.length-1:l.findIndex(c=>c>=a),u=r<0?l.length-1:r,i=x(e,t,o.weeks).slice(u),m=cardChartBox(i.length,o.weeks),k=weekChart({weeks:i,goal:n.goal},{weeks:m});return{week:n,shareable:n.count>0,fileName:`corner-office-week-of-${n.key}.jpg`,lines:d(n,C.format(f(n.key)),o.url),chart:{...k,goal:n.goal}}}export function onGoalLine(e,s,t=LAYOUT,o=.05){if(!e)return!1;const n=weekChart(s,t),a=1-e.y;return e.x>=n.x0-.02&&e.x<=n.x1+.08&&Math.abs(a-n.goalY)<=o}function h(e){return`${Math.round(e*100)}%`}export function bigNumbers(e){const s=e.response;return[{value:s.rate==null?"None yet":h(s.rate),label:s.rate==null?"replies so far":"heard back"},{value:s.medianDays==null?"None yet":`${s.medianDays} ${s.medianDays===1?"day":"days"}`,label:"to a first reply"}]}export function summaryLines(e){const s=[],t=(a,l,r=`${l}s`)=>`${a} ${a===1?l:r}`;s.push(`This week: ${t(e.thisWeek.count,"application")} sent, against a goal of ${e.goal}.`);const o=e.funnel.filter(a=>a.count>0).map(a=>`${a.label} ${a.count}`);s.push(o.length?`How far they got: ${o.join(", ")}.`:"Nothing has been sent yet.");const n=e.response;if(n.rate!=null){const a=n.medianDays==null?"":`, usually within ${t(n.medianDays,"day")}`;s.push(`Companies replied to ${n.replied} of ${n.sent} (${h(n.rate)})${a}.`)}return e.quiet&&s.push(`${t(e.quiet,"application has","applications have")} gone quiet.`),s}
